 ```powershell
# OutageAnalyzer.ps1 - AI-augmented incident analysis
param([switch]$Analyze)

$script:Config = @{
    Servers = @('srvr-auto','srvr-autoagent1','srvr-autoagent2','srvr-autoagent3','srvr-autoagent4')
    IncidentFile = Join-Path $PSScriptRoot "incidents.json"
    LogHours = 24
    Architecture = @"
System: Blue Prism (Automate) automation platform
- srvr-auto: Hosts both Execution Server (runs workflows) and Management Server (UI/manual control)
- srvr-autoagent1-4: Additional Execution Servers (part of 5-agent pool including srvr-auto's agent)
- All agents depend on srvr-auto's management/database services
- Cascading failures typically start at srvr-auto and propagate to agents
"@
}

function Get-RecentErrors {
    $since = (Get-Date).AddHours(-$script:Config.LogHours)
    $events = foreach($srv in $script:Config.Servers){
        try{
            Get-WinEvent -ComputerName $srv -LogName Application -ErrorAction Stop |
            Where-Object { $_.TimeCreated -ge $since -and $_.LevelDisplayName -match '^(Error|Warning)$' } |
            Select-Object @{N='Server';E={$srv}}, TimeCreated, LevelDisplayName, ProviderName, Id, Message
        }catch{
            Write-Host "⚠ Failed retrieving from $srv : $_" -ForegroundColor Red
        }
    }
    $events | Sort-Object TimeCreated
}

function Get-PastIncidents {
    if(Test-Path $script:Config.IncidentFile){
        Get-Content $script:Config.IncidentFile -Raw | ConvertFrom-Json
    }else{ @() }
}

function Save-Incident {
    param($Incident)
    $incidents = @(Get-PastIncidents) + $Incident
    $incidents | ConvertTo-Json -Depth 10 | Set-Content $script:Config.IncidentFile
    Write-Host "✓ Saved incident: $($Incident.root_cause)" -ForegroundColor Green
}

function Invoke-LLMAnalysis {
    param($Events, $PastIncidents)

    $prompt = @"
You are analyzing a Blue Prism automation platform outage.

ARCHITECTURE:
$($script:Config.Architecture)

PAST INCIDENTS (learn from these patterns):
$($PastIncidents | ConvertTo-Json -Depth 5)

CURRENT LOGS (last $($script:Config.LogHours)h, $($Events.Count) events):
$($Events | Select-Object Server, TimeCreated, LevelDisplayName, ProviderName, Id, @{N='MessagePreview';E={$_.Message.Substring(0,[Math]::Min(200,$_.Message.Length))}} | ConvertTo-Json -Depth 3)

TASK: Analyze and respond with ONE of these actions:

1. If you need more information, respond:
{
  "action": "request_info",
  "question": "your specific question here",
  "reasoning": "why you need this"
}

2. If you can diagnose the incident, respond:
{
  "action": "create_incident",
  "incident": {
    "timestamp": "ISO8601 when incident started",
    "affected_servers": ["server1", "server2"],
    "root_cause": "concise diagnosis",
    "error_signatures": ["key error patterns"],
    "severity": "high|medium|low",
    "status": "ongoing|resolved"
  }
}

Respond ONLY with valid JSON, no other text.
"@

    $body = @{
        model = "claude-sonnet-4-20250514"
        max_tokens = 2000
        messages = @(
            @{ role = "user"; content = $prompt }
        )
    } | ConvertTo-Json -Depth 10

    try{
        $response = Invoke-RestMethod -Uri "https://api.anthropic.com/v1/messages" `
            -Method Post `
            -Headers @{"Content-Type"="application/json"} `
            -Body $body

        $response.content[0].text | ConvertFrom-Json
    }catch{
        Write-Host "✗ LLM call failed: $_" -ForegroundColor Red
        $null
    }
}

# MAIN EXECUTION
if($Analyze){
    Write-Host "`n🔍 Gathering logs from $($script:Config.Servers.Count) servers..." -ForegroundColor Cyan
    $events = Get-RecentErrors

    if($events.Count -eq 0){
        Write-Host "✓ No errors/warnings found in last $($script:Config.LogHours)h" -ForegroundColor Green
        return
    }

    Write-Host "📊 Found $($events.Count) events, analyzing..." -ForegroundColor Cyan
    $pastIncidents = Get-PastIncidents
    $result = Invoke-LLMAnalysis -Events $events -PastIncidents $pastIncidents

    if($result){
        switch($result.action){
            "request_info" {
                Write-Host "`n❓ LLM needs more info:" -ForegroundColor Yellow
                Write-Host "   Q: $($result.question)" -ForegroundColor White
                Write-Host "   Why: $($result.reasoning)" -ForegroundColor Gray
            }
            "create_incident" {
                Write-Host "`n🚨 INCIDENT DETECTED:" -ForegroundColor Red
                $result.incident | Format-List
                Save-Incident $result.incident
            }
        }
    }
}else{
    Write-Host @"
OutageAnalyzer - AI-augmented incident analysis

Usage:
  .\OutageAnalyzer.ps1 -Analyze    Run analysis on last $($script:Config.LogHours)h of logs

Incidents stored in: $($script:Config.IncidentFile)
"@ -ForegroundColor Cyan
}
```

Ready to test. Run `.\OutageAnalyzer.ps1 -Analyze` to start. It'll pull logs, send to Claude, and either ask you questions or create an incident. No API key handling yet - you'll need to add that or it'll fail on the API call. Want me to add key management?

