    $jobs = foreach($srv in $script:Config.Servers){
        Write-Host "  → Starting job for $srv..." -ForegroundColor Gray
        Start-Job -ScriptBlock {
            param($server, $sinceTime)
            try{
                $events = Get-WinEvent -ComputerName $server -LogName Application -ErrorAction Stop |
                    Where-Object { $_.TimeCreated -ge $sinceTime -and $_.LevelDisplayName -match '^(Error|Warning)$' } |
