                @{Success=$true; Server=$server; Events=$events; Count=$events.Count}
            }catch{
                @{Success=$false; Server=$server; Error=$_.Exception.Message}
            }
        } -ArgumentList $srv, $since
    }

    Write-Host "  → Waiting for $($jobs.Count) jobs to complete..." -ForegroundColor Gray
    $results = $jobs | Wait-Job | Receive-Job
    $jobs | Remove-Job

    $allEvents = @()
    foreach($result in $results){
        if($result.Success){
            Write-Host "  ✓ $($result.Server): $($result.Count) events" -ForegroundColor Green
            $allEvents += $result.Events
        }else{
            Write-Host "  ✗ $($result.Server): $($result.Error)" -ForegroundColor Red
        }
