 **Stable solution: Pre-aggregate before range calculation.**

Instead of processing 73k individual timestamps, bin them first:

```powershell
function Get-TimeRanges {
    param([DateTime[]]$Times)

    if($Times.Count -eq 0){ return @() }
    if($Times.Count -eq 1){ return @(@{Start=$Times[0]; End=$Times[0]; Count=1}) }

    $sorted = $Times | Sort-Object

    # For very high frequency patterns (>1000 events), bin into 1-minute buckets first
    if($sorted.Count -gt 1000){
        $binned = $sorted | Group-Object { $_.ToString('yyyy-MM-dd HH:mm') } | ForEach-Object {
            [PSCustomObject]@{
                Time = [DateTime]::Parse($_.Name + ':00')
                Count = $_.Count
            }
        }
        # Now work with binned data
        $ranges = @()
        $currentRange = @{Start=$binned[0].Time; End=$binned[0].Time; Count=$binned[0].Count}

        for($i = 1; $i -lt $binned.Count; $i++){
            $gapMinutes = ($binned[$i].Time - $currentRange.End).TotalMinutes

            # 5+ minute gap = new range
            if($gapMinutes -gt 5){
                $ranges += $currentRange
                $currentRange = @{Start=$binned[$i].Time; End=$binned[$i].Time; Count=$binned[$i].Count}
            }else{
                $currentRange.End = $binned[$i].Time
                $currentRange.Count += $binned[$i].Count
            }
        }
        $ranges += $currentRange
        return $ranges
    }

    # Original algorithm for <1000 events
    $ranges = @()
    $currentRange = @($sorted[0])
    $intervals = @()

    for($i = 1; $i -lt $sorted.Count; $i++){
        $gap = ($sorted[$i] - $sorted[$i-1]).TotalMinutes

        if($intervals.Count -eq 0){
            $threshold = $script:Config.DefaultGapMinutes
        }else{
            $avgInterval = ($intervals | Measure-Object -Average).Average
            $multiplier = if($avgInterval -lt 10/60){ 30 }else{ $script:Config.GapMultiplier }
            $threshold = $avgInterval * $multiplier
        }

        if($gap -gt $threshold){
            $ranges += @{Start=$currentRange[0]; End=$currentRange[-1]; Count=$currentRange.Count}
            $currentRange = @($sorted[$i])
            $intervals = @()
        }else{
            $currentRange += $sorted[$i]
            $intervals += $gap
        }
    }

    $ranges += @{Start=$currentRange[0]; End=$currentRange[-1]; Count=$currentRange.Count}
    $ranges
}
```

**Why this works:**
- 73k events → ~1000 1-minute bins (fast grouping)
- Simple 5-minute gap rule on bins
- No adaptive calculation overhead for massive patterns
- Still uses adaptive logic for smaller patterns where precision matters

Reliable, fast, and scales to millions of events.

